module prienc4(input [3:0] in, output reg [1:0] out, output reg valid);
  always @(*) begin
    valid = |in;
    casez (in)
      4'b1???: out = 2'd3;
      4'b01??: out = 2'd2;
      4'b001?: out = 2'd1;
      4'b0001: out = 2'd0;
      default: out = 2'd0;
    endcase
  end
endmodule

